'use strict';
const chapters=[["Rua das Cinzas","A noite da Ruptura","Ruas abandonadas, arquitetura gótica e o primeiro passo rumo ao Véu."],["Distrito do Vinil","Frequências proibidas","Luzes frias, música esquecida e os sinais de que algo atravessou a fronteira."],["Catedral do Sangue","Ecos do passado","Vitrais, corredores antigos e uma presença que observa em silêncio."],["Laboratório Eclipse","O preço da experiência","Máquinas, contenção e perguntas que ninguém deveria ter feito."],["Jardim dos Ecos","Além do conhecido","Pontes e ruínas em um espaço onde a memória parece ganhar corpo."],["Observatório Vespera","Sob o último céu","A cidade e o Véu se encontram diante de um horizonte desconhecido."]];
const tabs=[...document.querySelectorAll('[data-chapter]')];
function selectChapter(index,focus=false){const [place,title,description]=chapters[index];tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1});document.querySelector('#chapter-title').textContent=title;document.querySelector('#chapter-description').textContent=description;document.querySelector('#chapter-image').src=`assets/map${index+1}.png`;document.querySelector('#chapter-image').alt=`${place}, cena do projeto na Unity`;document.querySelector('#chapter-view').setAttribute('aria-labelledby',tabs[index].id);const button=document.querySelector('#chapter-view .screenshot');button.dataset.zoom=`assets/map${index+1}.png`;button.dataset.caption=`${place} — registro visual anterior da cena na Unity`;button.setAttribute('aria-label',`Ampliar imagem de ${place}`);if(focus)tabs[index].focus()}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectChapter(index));tab.addEventListener('keydown',e=>{let next=index;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();selectChapter(next,true)})});
const lightbox=document.querySelector('#lightbox');let previousFocus;
document.querySelectorAll('[data-zoom]').forEach(button=>button.addEventListener('click',()=>{previousFocus=button;lightbox.querySelector('img').src=button.dataset.zoom;lightbox.querySelector('img').alt=button.dataset.caption;lightbox.querySelector('p').textContent=button.dataset.caption;lightbox.showModal()}));
lightbox.querySelector('.close').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',event=>{if(event.target===lightbox){const r=lightbox.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)lightbox.close()}});lightbox.addEventListener('close',()=>previousFocus?.focus());
